-- ----------------------------
-- Table structure for portal_vendor_field_mapping
-- ----------------------------
DROP TABLE IF EXISTS `portal_vendor_field_mapping`;
CREATE TABLE `portal_vendor_field_mapping`  (
  `mapping_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `vendor_id` bigint NOT NULL COMMENT '供应商ID',
  `vendor_template` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '模板标识（原 supplier_template 改为 vendor_template）',
  `source_field` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源字段（供应商侧列名/字段）',
  `use_example_source_field` tinyint(1) NOT NULL DEFAULT 1 COMMENT '1=中文名+source_field 一起识别；0=仅按中文名',
  `output_header` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '输出表头（展示用）',
  `field_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '系统字段编码（关联 portal_bill_field_info.field_code）',
  `field_name_en` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '英文名称（可冗余）',
  `parent_code` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父字段编码',
  `parent_name_cn` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '父字段中文名',
  `insert_name` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '插入/写入名称（如目标列名/节点名）',
  `insert_order` int NULL DEFAULT 0 COMMENT '插入顺序',
  `enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用 0否 1是',
  `is_fixed_value` tinyint NOT NULL DEFAULT 0 COMMENT '是否固定值 0否 1是',
  `fixed_value` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '固定值（is_fixed_value=1 时使用）',
  `target_data_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标数据类型',
  `target_display_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '目标展示路径（如 Sheet/区块/层级路径）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `create_time` datetime NULL DEFAULT NULL,
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `update_time` datetime NULL DEFAULT NULL,
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  PRIMARY KEY (`mapping_id`) USING BTREE,
  UNIQUE INDEX `uk_vendor_template_source_field`(`vendor_id`, `vendor_template`, `source_field`, `field_code`) USING BTREE,
  INDEX `idx_vendor`(`vendor_id`) USING BTREE,
  INDEX `idx_field_code`(`field_code`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 838 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '供应商字段映射总表' ROW_FORMAT = DYNAMIC;

